require 'object'
local message = require 'message'
--require 'pl'
local tablex = require 'pl.tablex'
---------------------------------------------------------------------
-- Setting class
--
-- Setting objects define the interface between the UI and the underlying
-- editable data.
--
-- During development, some Setting objects are automatically generated by
-- this code for convenience. The auto-generated settings get/set hidden data
-- parameters. The final code will access the real settings so the final
-- code should not have auto-generated Setting  objects.
---------------------------------------------------------------------

SettingBase = Object:subclass('SettingBase')
SettingBase:attributes{ 'name', 'title', 'text', 'graphic', 'default', 'map', 'index', 'storage', 'array', 'description', 'save', 'protocol' }
SettingBase.notify = message.createMessageCenter('settings')
SettingBase.save = true

-- Generate a dot-separated name for auto-created setting (for development)
function SettingBase.autoname()
    autosettingCount = autosettingCount + 1
    return 'autosetting.' .. autosettingCount
end

-- Constructor
function SettingBase:__init(items)
    items = items or { }
    super(SettingBase).__init(self,  items)
--  print('SettingBase:__init', items)
    local initialValue = items[1]   -- optional; can be nil
    if not self.default then self.default = initialValue end

    assert(not self.map or type(self.map) == 'table')

    --self.name = self.name or SettingBase.autoname()
    --assert(self.name:find('.'))

    -- Add to table of settings objects (don't allow duplicates)
    self.color = items.color

    -- Create object for storing the data if not already assigned
    if not self.storage then
        if self.array then self.storage = Storage()
        else self.storage = Storage(initialValue)
        end
    else
        assert(isinstance(self.storage, Storage))
    end

    if self.name then SettingRegister(self) end

end

function SettingBase:subscribe(method, ...)
    self.notify:subscribe({ self.name, noMsg=true }, method, ...)
end

function SettingBase:indexIsValid(index)
    local idx = type(index) == 'table' and index or { index }
    local arr = type(self.array) == 'table' and self.array or { self.array }
    if #idx ~= #arr then return false end
    for i = 1,#arr do
        if idx[i] < 1 or idx[i] > arr[i] then
            return false
        end
    end
    return true
end

function SettingBase:value(index)
    local v = self.storage:value(index)
    if not v and self.array and index then
        local n = type(index) == 'table' and #index or 1
        if n ~= #self.array then return { } end
    end
    return v or self:defaultValue(index)
end

function SettingBase:defaultValue(index)
    return self.default
end

function SettingBase:sendChangeNotification(index)
    if self.onChanged then self:onChanged(index) end
    self.notify:send(self.name, self, index)
    message.send('setting.changed', self, index)
--  message.send('setting.' .. self.name, self, index)
end

function SettingBase:setValue(v, index)
    self.storage:setValue(v, index)
    self:sendChangeNotification(index)
end

function SettingBase:rawtext(index)
    local val = self:value(index)
    return val == nil and '' or tostring(val)
end

function SettingBase:text(index)
    local s = self:rawtext(index)
    if self.map and self.map[s] then s = self.map[s]
    elseif self.units then s = s .. self.units end
    return s
end

function SettingBase:setText(s, index)
    self:setValue(s, index)
end

function SettingBase:incValue(index)
    print('Ignoring call to SettingBase:incValue for ' .. self.__classname .. ' ' .. self.name)
end

function SettingBase:graphic(index)
    return nil
end

--[[
function SettingBase:incValue(index)
    error('Unexpected call to SettingBase:incValue for ' .. self.__classname)
end
--]]
function SettingBase:clear(index)
    self:setValue(nil, index )
end

function SettingBase:setStorage(storage)
    if not isinstance(storage, Storage) then
        storage = Storage(storage)
    end
    assert(isinstance(storage, Storage))
    self.storage = storage
    self:sendChangeNotification()
end

function SettingBase:count(v, index)
    return self.storage:count(v, index)
end

-------------------------------------------------------------------
SettingTable = SettingBase:subclass('SettingTable')
function SettingTable:value(index)
    local value = super(SettingTable).value(self, index)
    if value == nil then
        return { }
    else
        return tablex.deepcopy(value)
    end
end

function SettingTable:defaultValue(index)
    return self.default and tablex.deepcopy(self.default) or { }
end

-------------------------------------------------------------------
SettingMenu = SettingBase:subclass('SettingMenu')
SettingMenu:attributes{ 'menu', 'menus', 'units' }
function SettingMenu:__init(items)

    if items.menu then  -- TODO: clean up!
        items.menus = items.menu
        items.menu = nil
    end

    super(SettingMenu).__init(self, items)
    assert(not items.range)

--  if self.menu then
--      assert(not items.menus)
--      self.menu = Menu(items.menu);
--      self.default = self.default or self.menu:valueForIndex(1)
    if self.menus then
        if type(self.menus[1]) == 'string' then
            self.menus = { Menu(self.menus) }
        elseif isinstance(self.menus, Menu) then
            self.menus = { self.menus }
        elseif type(self.menus[1]) == 'table' then
            assert(not self.menus.__classname)
            self.menus = { Menu(self.menus) }
        end
        for _,m in pairs(self.menus) do
            assert(isinstance(m, Menu),  'Expecting Menu objects')
        end

    end
end

function SettingMenu:defaultValue(index)
    return self.default or self:menu(index):valueForIndex(1)
end

function SettingMenu:menu(index)
    local i = ((type(index)=='number') and index) or (index and index[#index])
    return (self.menus and i and self.menus[i]) or (self.menus and self.menus[1]) or self.menuDefault
end

function SettingMenu:rawtext(index)
    local v = self:value(index)
    return self:menu(index):textForValue(v)
end

function SettingMenu:setText(s, index)
    local v = self:menu(index):valueForText(s)
    self:setValue(v, index)
end

function SettingMenu:incValue(index, step)
    local value = self:value(index)
    value = self:menu(index):incValue(value, step)
    self:setValue(value, index)
end

function SettingMenu:textList()
    return self:menu():textList()
end

-------------------------------------------------------------------
SettingNumber = SettingBase:subclass('SettingNumber')
SettingNumber:attributes{ 'zero', 'range', 'units' }
function SettingNumber:__init(items)
    local fmt
    local mask = '' -- QLineEdit/QTextEdit.inputMask
    items[1] = items[1] or (self.range and self.range[1]) -- initial value if not already defined
    super(SettingNumber).__init(self, items)

    if self.zero then
        self.map = self.map or { }
        self.map["0"] = self.zero
    end

    -- For numeric, determine the format string and integer scaling from
    -- the range. For example, range={0, 5, 0.1} represents a
    -- numeric range 0 to 5 in steps of 0.1, so underlying data is
    -- an integer in range 0 to 50 and scaling factor is 10.
    local minValue, maxValue = self.range[1], self.range[2]
    local decimalPlaces = 0
    local step = self.range[3] or self.range.step or 1
    local scaling = step < 1 and 1/step or 1
    minValue, maxValue = minValue * scaling, maxValue * scaling
    while step < 1 do
        decimalPlaces = decimalPlaces + 1
        step = step * 10
    end
    assert(step >= 1.0)
    if decimalPlaces >= 1 then
        fmt = '%d.%0'.. decimalPlaces .. 'd'
    else
        fmt = '%d'
    end
    local editstr = string.format(fmt, math.max(math.abs(minValue), math.abs(maxValue))/scaling, 0)
    editstr = editstr:gsub('%d', '_')
    fmt = fmt .. (self.units or '')
--  editstr = editstr .. (self.units or '')
    if minValue < 0 then editstr = '+' .. editstr end
--  dprint('>>', fmt, editstr)
    local default = self.default or (self.range and self.range[1] > 0 and self.range[1]) or 0
    --if default and scaling ~= 1 then default = default * scaling end
    self.default = default
    self.format = fmt
    self.template = editstr:gsub('_','0'):gsub('+','#')
    self.scaling = scaling
    if not self.maxchars then
        local n = 0
        for c in editstr:gmatch('_') do n = n + 1 end
        self.maxchars = n
    end
end

-- 'index' is optional; only passed for array-based settings otherwise nil
function SettingNumber:setValue(v, index)
    v = tonumber(v)
    if v == nil then return end
    if self.range then
        if self.range.step then -- round up to 'step' interval
            v = math.floor( (v / self.range.step) + 0.5) * self.range.step
        end
        if v < self.range[1] then v = self.range[1] end
        if v > self.range[2] then v = self.range[2] end
    end
    super(SettingNumber).setValue(self, tonumber(v), index)
end

function SettingNumber:incValue(index, step)
    local v = self:value(index)
    local scale = self.range and self.range.step or 1
    local wrap = (step == nil)
    step = (step or 1) * scale
    v = v + step
    if self.range then
        if v < self.range[1] then v = wrap and self.range[2] or self.range[1] end
        if v > self.range[2] then v = wrap and self.range[1] or self.range[2] end
    end
    self:setValue(v, index)
end

-------------------------------------------------------------------
SettingText = SettingBase:subclass('SettingText')
SettingText.maxchars = 32
SettingText.default = ''
SettingText:attributes{ 'maxchars' }
function SettingText:__init(items)
    super(SettingText).__init(self, items)
end

-------------------------------------------------------------------
SettingTimecode = SettingBase:subclass('SettingTimecode')
SettingTimecode:attributes{ 'timecode' }
SettingTimecode.maxchars = 8
SettingTimecode.default = 0
-------------------------------------------------------------------
SettingUserbits = SettingBase:subclass('SettingUserbits')
SettingUserbits:attributes{ 'userbits' }
SettingUserbits.maxchars = 8
SettingUserbits.default = 0

-------------------------------------------------------------------
-- Factory function that creates an appropriate setting
-- object according to the 'items' attributes.
-- Also allows for various shorthand descriptions
function Setting(items)
    if type(items) == 'string' then return SettingFind(items) end

    if items.range then return SettingNumber(items)
    elseif items.menu or items.menus then return SettingMenu(items)
    elseif items.timecode then return SettingTimecode(items)
    elseif items.userbits then return SettingUserbits(items)
    elseif type(items[1])=='string' then
        if #items > 1 then
            -- E.g. Setting{ 'OFF', 'ON' } produces  menu
            items.menu = { }
            while #items > 0 do
                local v = table.remove(items,  1)
                assert(type(v)=='string')
                table.insert(items.menu, v)
            end
            return SettingMenu(items)
        end
        return SettingText(items)
    elseif type(items[1])=='number' and (#items==2 or #items==3) then
        items.range = { }
        while #items > 0 do
            local v = table.remove(items,  1)
            assert(type(v)=='number')
            table.insert(items.range, v)
        end
        return SettingNumber(items)
    elseif items.maxchars  then
        return SettingText(items)
    else
        return SettingBase(items)
        --error('Unknown setting type')
    end
end

